public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    static long brute(int[] a) {
        long best = Long.MIN_VALUE;
        for (int i = 0; i < a.length; i++) {
            long pr = 1;
            for (int jj = i; jj < a.length; jj++) {
                pr *= a[jj];
                best = Math.max(best, pr);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("RUN")) {
                    r = String.valueOf(Product.maxProduct(arr(p[1])));
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(25);
                    String sai = null;
                    for (int t = 0; t < 20000 && sai == null; t++) {
                        int[] a = new int[1 + rnd.nextInt(10)];
                        for (int i = 0; i < a.length; i++) {
                            a[i] = rnd.nextInt(11) - 5;
                        }
                        long got = Product.maxProduct(a.clone()), want = brute(a);
                        if (got != want) {
                            sai = str(a) + " -> " + got + ", expected " + want;
                        }
                    }
                    r = ketQua("20000 random arrays", 20000, sai);
                } else {
                    final int[] a = new int[1000000];
                    Random rnd = new Random(27);
                    int[] vals = {-2, -1, 1, 2, 3, -3};
                    for (int i = 0; i < a.length; i++) {
